// HasProject applies the HasEdge predicate on the "project" edge.
func HasProject() predicate.NativeRemediationRun {
	return predicate.NativeRemediationRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ProjectTable, ProjectColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProjectWith applies the HasEdge predicate on the "project" edge with a given conditions (other predicates).
func HasProjectWith(preds ...predicate.Project) predicate.NativeRemediationRun {
	return predicate.NativeRemediationRun(func(s *sql.Selector) {
		step := newProjectStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasDiagnostic applies the HasEdge predicate on the "diagnostic" edge.
func HasDiagnostic() predicate.NativeRemediationRun {
	return predicate.NativeRemediationRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DiagnosticTable, DiagnosticColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDiagnosticWith applies the HasEdge predicate on the "diagnostic" edge with a given conditions (other predicates).
func HasDiagnosticWith(preds ...predicate.NativeAiDiagnostic) predicate.NativeRemediationRun {
	return predicate.NativeRemediationRun(func(s *sql.Selector) {
		step := newDiagnosticStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.NativeRemediationRun) predicate.NativeRemediationRun {
	return predicate.NativeRemediationRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.NativeRemediationRun) predicate.NativeRemediationRun {
	return predicate.NativeRemediationRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.NativeRemediationRun) predicate.NativeRemediationRun {
	return predicate.NativeRemediationRun(sql.NotPredicates(p))
}
